(function() {
    console.log("🛠️ Axiom X-Ray Bot Injected!");

    // ১. স্টাইল (মেইন পাওয়ার মেনু)
    const style = document.createElement('style');
    style.innerHTML = `
        #xray-menu { position: fixed; top: 10px; left: 10px; z-index: 9999999; background: #202124; padding: 10px; border-radius: 12px; box-shadow: 0 4px 20px rgba(0,0,0,0.5); font-family: sans-serif; display: flex; flex-direction: column; gap: 8px; border: 1px solid #4285f4; }
        .xray-btn { background: #4285f4; color: white; border: none; padding: 8px 12px; border-radius: 6px; cursor: pointer; font-size: 12px; font-weight: bold; transition: 0.3s; text-align: left; }
        .xray-btn:hover { background: #34a853; }
        .xray-btn.active { background: #ea4335; }
        #xray-header { color: #aaa; font-size: 10px; text-align: center; margin-bottom: 5px; text-transform: uppercase; letter-spacing: 1px; }
    `;
    document.head.appendChild(style);

    // ২. মেনু তৈরি
    const menu = document.createElement('div');
    menu.id = 'xray-menu';
    menu.innerHTML = `
        <div id="xray-header">Axiom X-Ray Bot</div>
        <button class="xray-btn" id="btn-edit">✍️ Edit Anything (Off)</button>
        <button class="xray-btn" id="btn-pass">👁️ Show Passwords</button>
        <button class="xray-btn" id="btn-img">🖼️ Extract Images</button>
    `;
    document.body.appendChild(menu);

    // ৩. পাওয়ার ১: এডিট মোড (Design Mode)
    let isEditMode = false;
    document.getElementById('btn-edit').onclick = function() {
        isEditMode = !isEditMode;
        document.designMode = isEditMode ? 'on' : 'off';
        this.innerText = isEditMode ? '✍️ Edit Anything (On)' : '✍️ Edit Anything (Off)';
        this.classList.toggle('active');
        if(isEditMode) alert("ম্যাজিক অন! এখন পেজের যেকোনো লেখার ওপর ক্লিক করে নিজের ইচ্ছেমতো টাইপ করো। 😏");
    };

    // ৪. পাওয়ার ২: পাসওয়ার্ড আনমাস্কার
    document.getElementById('btn-pass').onclick = function() {
        const passwords = document.querySelectorAll('input[type="password"]');
        if (passwords.length > 0) {
            passwords.forEach(p => p.type = 'text');
            alert(`${passwords.length}টি পাসওয়ার্ড খুঁজে বের করা হয়েছে!`);
        } else {
            alert("এই পেজে কোনো পাসওয়ার্ড ফিল্ড পাওয়া যায়নি।");
        }
    };

    // ৫. পাওয়ার ৩: ইমেজ স্নিফার
    document.getElementById('btn-img').onclick = function() {
        const images = Array.from(document.querySelectorAll('img')).map(i => i.src);
        if (images.length === 0) {
            alert("কোনো ছবি পাওয়া যায়নি!");
            return;
        }

        let imgWin = window.open('', '_blank');
        let imgHTML = `
            <html><head><title>Axiom Image Sniffer</title>
            <style>
                body { background: #121212; color: white; font-family: sans-serif; text-align: center; padding: 20px; }
                .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 15px; }
                img { width: 100%; border-radius: 8px; border: 2px solid #444; transition: 0.3s; }
                img:hover { border-color: #4285f4; transform: scale(1.05); }
                .info { margin-bottom: 20px; }
            </style></head>
            <body>
                <div class="info"><h2>🖼️ Found ${images.length} Images</h2><p>ছবির ওপর চেপে ধরে ডাউনলোড করো!</p></div>
                <div class="grid">
        `;
        images.forEach(src => { if(src) imgHTML += `<img src="${src}">`; });
        imgHTML += `</div></body></html>`;

        imgWin.document.write(imgHTML);
        imgWin.document.close();
    };

})();
